part 'database.g.dart';

/// One night of sleep. A manual log fills only bedtime and wake time (plus
/// optional heart data). Health Connect imports will fill the stages.
@DataClassName('SleepEntry')
class SleepEntries extends Table {
  IntColumn get id => integer().autoIncrement()();
  DateTimeColumn get bedtime => dateTime()();
  DateTimeColumn get wakeTime => dateTime()();

  IntColumn get deepMinutes => integer().nullable()();
  IntColumn get remMinutes => integer().nullable()();
  IntColumn get lightMinutes => integer().nullable()();

  IntColumn get restingHeartRate => integer().nullable()();
  IntColumn get hrvMs => integer().nullable()();

  /// Morning check-in, 1 (drained) to 5 (fresh).
  IntColumn get mood => integer().nullable()();

  /// 'manual' or 'health_connect'.
  TextColumn get source => text().withDefault(const Constant('manual'))();
}

/// App settings. Always exactly one row, with id 1.
@DataClassName('SettingsRow')
class AppSettings extends Table {
  IntColumn get id => integer().withDefault(const Constant(1))();
  TextColumn get userName => text().withDefault(const Constant('Chauka'))();

  /// Sleep goal in minutes (480 = 8 hours).
  IntColumn get sleepGoalMinutes =>
      integer().withDefault(const Constant(480))();

  /// Bedtime goal as minutes after midnight (1365 = 10:45 PM).
  IntColumn get bedtimeGoalMinutes =>
      integer().withDefault(const Constant(1365))();

  BoolColumn get bedtimeReminder =>
      boolean().withDefault(const Constant(true))();

  @override
  Set<Column> get primaryKey => {id};
}

@DriftDatabase(tables: [SleepEntries, AppSettings])
class AppDatabase extends _$AppDatabase {
  AppDatabase([QueryExecutor? executor])
      : super(executor ?? _openConnection());

  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        beforeOpen: (details) async {
          // Make sure the single settings row exists.
          await into(appSettings).insert(
            AppSettingsCompanion(id: const Value(1)),
            mode: InsertMode.insertOrIgnore,
          );
        },
      );

  // ---------- Nights ----------

  /// Newest night first. The home screen uses the first one, and the rest
  /// as history for the score.
  Stream<List<SleepEntry>> watchRecentNights({int limit = 15}) {
    return (select(sleepEntries)
          ..orderBy([(t) => OrderingTerm.desc(t.wakeTime)])
          ..limit(limit))
        .watch();
  }

  Future<int> addManualNight({
    required DateTime bedtime,
    required DateTime wakeTime,
    int? restingHeartRate,
    int? hrvMs,
  }) {
    return into(sleepEntries).insert(
      SleepEntriesCompanion.insert(
        bedtime: bedtime,
        wakeTime: wakeTime,
        restingHeartRate: Value(restingHeartRate),
        hrvMs: Value(hrvMs),
      ),
    );
  }

  Future<void> setMood(int nightId, int mood) async {
    await (update(sleepEntries)..where((t) => t.id.equals(nightId)))
        .write(SleepEntriesCompanion(mood: Value(mood)));
  }

  Future<void> deleteNight(int nightId) async {
    await (delete(sleepEntries)..where((t) => t.id.equals(nightId))).go();
  }

  // ---------- Settings ----------

  Stream<SettingsRow> watchSettings() {
    return (select(appSettings)..where((t) => t.id.equals(1))).watchSingle();
  }

  Future<void> setBedtimeGoal(int minutesAfterMidnight) {
    return _updateSettings(
      AppSettingsCompanion(bedtimeGoalMinutes: Value(minutesAfterMidnight)),
    );
  }

  Future<void> setBedtimeReminder(bool on) {
    return _updateSettings(AppSettingsCompanion(bedtimeReminder: Value(on)));
  }

  Future<void> setSleepGoal(int minutes) {
    return _updateSettings(
      AppSettingsCompanion(sleepGoalMinutes: Value(minutes)),
    );
  }

  Future<void> _updateSettings(AppSettingsCompanion changes) async {
    await (update(appSettings)..where((t) => t.id.equals(1))).write(changes);
  }

  static QueryExecutor _openConnection() {
    return driftDatabase(
      name: 'sleep_tracker',
      native: const DriftNativeOptions(
        databaseDirectory: getApplicationSupportDirectory,
      ),
    );
  }
}

/// Database row -> UI model.
extension SleepEntryToModel on SleepEntry {
  SleepNight toModel() {
    final deep = deepMinutes;
    final rem = remMinutes;
    final light = lightMinutes;
    return SleepNight(
      id: id,
      bedtime: bedtime,
      wakeTime: wakeTime,
      stages: (deep != null && rem != null && light != null)
          ? SleepStages(
              deep: Duration(minutes: deep),
              rem: Duration(minutes: rem),
              light: Duration(minutes: light),
            )
          : null,
      restingHeartRate: restingHeartRate,
      hrvMs: hrvMs,
      mood: mood,
    );
  }
}
